// Build per-provider Perplexity prompts from the LIVE pricing table. Nothing about the table is hardcoded:
// providers, model ids and source domains all derive from the fetch at runtime. One output item per provider.
const raw = $input.first().json;
const table = typeof raw === 'string' ? JSON.parse(raw)
  : (typeof raw.data === 'string' ? JSON.parse(raw.data) : raw);

const SKIP = new Set(['$schema', 'versionedAt']);
const providers = Object.keys(table).filter(k => !SKIP.has(k) && table[k] && typeof table[k] === 'object');
// Official pricing hosts, added to whatever hostnames the table's own sourceUrl fields already cite.
const OFFICIAL = {
  anthropic: ['platform.claude.com', 'docs.anthropic.com', 'anthropic.com'],
  openai: ['openai.com', 'platform.openai.com'],
  gemini: ['ai.google.dev', 'cloud.google.com'],
  deepseek: ['api-docs.deepseek.com'],
  perplexity: ['docs.perplexity.ai'],
  xai: ['docs.x.ai', 'x.ai']
};
const today = new Date().toISOString().slice(0, 10);

return providers.map(function(p) {
  const models = Object.keys(table[p]);
  const hosts = new Set(OFFICIAL[p] || []);
  models.forEach(function(m) {
    const u = table[p][m] && table[p][m].sourceUrl;
    const h = typeof u === 'string' && /^https?:\/\/([^\/]+)/i.exec(u);
    if (h) hosts.add(h[1].replace(/^www\./, ''));
  });
  const domains = Array.from(hosts).slice(0, 20);
  const driftPrompt =
    'Today is ' + today + '. Using the provider\'s official pricing pages, return ONLY a JSON object (no prose, no markdown) ' +
    'keyed by model id, giving the CURRENT standard list price (non-batch, non-cached, short-context) in USD per 1,000,000 tokens, ' +
    'plus lifecycle status. Shape exactly: {"model-id":{"input":<number>,"output":<number>,"status":"active"|"deprecated"|"retired","shutdown_date":"YYYY-MM-DD"|null}}. ' +
    'If you cannot find a reliable current price for a model, set its whole value to null. Provider: ' + p + '. Models:\n' + models.join(', ');
  const newModelsPrompt =
    'Today is ' + today + '. List every ' + p + ' API model that is CURRENTLY offered (generally available or public preview) and is NOT in the Known list below. ' +
    'Include new versions, new tiers and new variants of existing families. TEXT / CHAT / REASONING / CODING models only — exclude embeddings, image, video, audio/speech/TTS, realtime, moderation and fine-tune-only models. Use the exact API model id. ' +
    'Return ONLY a JSON object (no prose, no markdown) of shape {"models":{"exact-api-model-id":{"input":<number>|null,"output":<number>|null,' +
    '"status":"ga"|"preview","released":"YYYY-MM-DD"|null,"replaces":"older-model-id"|null,"notes":"<=140 chars"}}}. ' +
    'Prices are USD per 1,000,000 tokens (standard, non-batch). "replaces" is the older model this one succeeds, if the provider says so. ' +
    'If there are none, return {"models":{}}. Known models: ' + models.join(', ');
  return { json: { provider: p, today, domains, driftPrompt, newModelsPrompt } };
});

// Deterministic comparison — NO LLM. Covers: price drift, lifecycle (deprecations), NEW MODELS, and
// upgrade recommendations (is the newer model cheaper than the one it replaces?).
const THRESHOLD = 5;        // percent, on input OR output, to call drift
const CHEAPER_PCT = 10;     // blended-price gap needed to recommend / warn
const BLEND_IN = 3, BLEND_OUT = 1; // blended price assumes a 3:1 input:output token mix
const NOTION_RT_MAX = 2000;
const queries = $('Build queries').all().map(i => i.json);
const driftResp = $('Perplexity — drift').all();
const newResp = $('Perplexity — new models').all();
const today = queries[0] ? queries[0].today : new Date().toISOString().slice(0, 10);

const rawTable = $('Fetch live table.json').first().json;
const table = typeof rawTable === 'string' ? JSON.parse(rawTable)
  : (typeof rawTable.data === 'string' ? JSON.parse(rawTable.data) : rawTable);

function extractJson(content) {
  if (content == null) return null;
  if (typeof content === 'object') return content;
  const s = String(content), a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a === -1 || b === -1) return null;
  try { return JSON.parse(s.slice(a, b + 1)); } catch (e) { return null; }
}
function chunkText(text, maxLen) {
  if (!text) return [];
  const chunks = []; let cur = '';
  for (const line of text.split('\n')) {
    const cand = cur ? cur + '\n' + line : line;
    if (cand.length > maxLen) {
      if (cur) chunks.push(cur);
      if (line.length > maxLen) { let rest = line; while (rest.length > maxLen) { chunks.push(rest.slice(0, maxLen)); rest = rest.slice(maxLen); } cur = rest; }
      else cur = line;
    } else cur = cand;
  }
  if (cur) chunks.push(cur);
  return chunks;
}
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-?\d{4}-\d{2}-\d{2}$/, '').replace(/-?\d{8}$/, '').replace(/^-+|-+$/g, '');
const num = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const blend = (i, o) => (i == null || o == null) ? null : (BLEND_IN * i + BLEND_OUT * o) / (BLEND_IN + BLEND_OUT);
const money = v => v == null ? '?' : '$' + (Math.round(v * 1000) / 1000);

// family/version parsing for "which model does this one succeed?"
const NOISE = new Set(['preview', 'latest', 'exp', 'experimental']);
function parseId(id) {
  const toks = norm(id).split('-').filter(Boolean);
  const ver = [], fam = [];
  for (const t of toks) {
    const m = /^v?(\d+)$/.exec(t);
    if (m) ver.push(Number(m[1])); else if (!NOISE.has(t)) fam.push(t);
  }
  return { family: fam.join('-'), version: ver };
}
function cmpVer(a, b) {
  for (let i = 0; i < Math.max(a.length, b.length); i++) { const d = (a[i] || 0) - (b[i] || 0); if (d) return d; }
  return 0;
}

// Table index: normalised id -> {provider, model, in, out}
const known = {};
const byProvider = {};
for (const p of Object.keys(table)) {
  if (p === '$schema' || p === 'versionedAt' || typeof table[p] !== 'object') continue;
  byProvider[p] = [];
  for (const m of Object.keys(table[p])) {
    const t = table[p][m] || {};
    const rec = { provider: p, model: m, in: num(t.inputPer1M), out: num(t.outputPer1M), alias: !!t.deprecatedAliasFor };
    rec.blend = blend(rec.in, rec.out);
    Object.assign(rec, parseId(m));
    known[p + '/' + norm(m)] = rec;
    byProvider[p].push(rec);
  }
}

const NON_TEXT = /embed|tts|whisper|transcribe|speech|audio|realtime|image|imagen|dall-?e|veo|sora|video|moderation|rerank|live/i;
const MAX_CANDIDATES = 25;
let filteredNonText = 0;
const STALE_DAYS = 90;
const gaps = [];          // provider lookups that failed or were unparseable
const driftResults = [];
const deprecations = [];
const candidates = [];
let anyParsed = false;

queries.forEach(function(q, idx) {
  const p = q.provider;
  const dc = driftResp[idx] && driftResp[idx].json && driftResp[idx].json.choices && driftResp[idx].json.choices[0] && driftResp[idx].json.choices[0].message ? driftResp[idx].json.choices[0].message.content : null;
  const nc = newResp[idx] && newResp[idx].json && newResp[idx].json.choices && newResp[idx].json.choices[0] && newResp[idx].json.choices[0].message ? newResp[idx].json.choices[0].message.content : null;
  const detected = extractJson(dc);
  const newObj = extractJson(nc);
  if (!detected) gaps.push(p + ' (price/lifecycle lookup failed)'); else anyParsed = true;
  if (!newObj) gaps.push(p + ' (new-model lookup failed)'); else anyParsed = true;

  for (const rec of byProvider[p] || []) {
    const d = detected ? (detected[rec.model] || detected[norm(rec.model)]) : null;
    if (!detected) continue;               // whole lookup failed: reported as a gap, not as per-model UNVERIFIABLE
    if (!d || num(d.input) == null || num(d.output) == null) { driftResults.push({ p, m: rec.model, cls: 'UNVERIFIABLE' }); }
    else {
      const dIn = num(d.input), dOut = num(d.output);
      const deltaIn = rec.in ? Math.abs(dIn - rec.in) / rec.in * 100 : 0;
      const deltaOut = rec.out ? Math.abs(dOut - rec.out) / rec.out * 100 : 0;
      const drift = deltaIn >= THRESHOLD || deltaOut >= THRESHOLD;
      driftResults.push({ p, m: rec.model, cls: drift ? 'DRIFT' : 'MATCH', tIn: rec.in, tOut: rec.out, dIn, dOut, deltaIn: +deltaIn.toFixed(1), deltaOut: +deltaOut.toFixed(1) });
    }
    if (d && (d.status === 'deprecated' || d.status === 'retired' || d.shutdown_date)) {
      if (!rec.alias) deprecations.push({ p, m: rec.model, status: d.status || 'deprecated', shutdown: d.shutdown_date || null });
    }
  }

  if (newObj) {
    const models = newObj.models && typeof newObj.models === 'object' ? newObj.models : newObj;
    for (const id of Object.keys(models || {})) {
      if (known[p + '/' + norm(id)]) continue;          // already in the table (ID-format differences normalised)
      if (NON_TEXT.test(id)) { filteredNonText++; continue; }  // table prices text models per 1M tokens only
      const v = models[id] || {};
      const cand = { p, m: id, in: num(v.input), out: num(v.output), status: v.status || null, released: v.released || null, replaces: v.replaces || null, notes: v.notes || '' };
      cand.blend = blend(cand.in, cand.out);
      Object.assign(cand, parseId(id));
      // predecessor: the provider's stated "replaces" if it is in the table, else highest older version in the same family
      let pred = cand.replaces ? known[p + '/' + norm(cand.replaces)] : null;
      if (!pred && cand.family && cand.version.length) {
        const older = (byProvider[p] || []).filter(r => !r.alias && r.family === cand.family && r.version.length && cmpVer(r.version, cand.version) < 0)
          .sort((a, b) => cmpVer(b.version, a.version));
        pred = older[0] || null;
      }
      cand.pred = pred;
      if (cand.blend == null) cand.rec = 'PRICE UNVERIFIED — check the official pricing page before adding.';
      else if (!pred || pred.blend == null) cand.rec = 'NEW — no predecessor found in the table; add it, and compare against the closest model you use today.';
      else {
        const pct = (pred.blend - cand.blend) / pred.blend * 100;
        const cmp = money(cand.blend) + ' vs ' + money(pred.blend) + ' blended per 1M (3:1 in:out)';
        if (pct >= CHEAPER_PCT) cand.rec = '💡 CHEAPER — ' + Math.round(pct) + '% cheaper than ' + pred.model + ' (' + cmp + '). Consider migrating where it matches or beats capability; check benchmarks first.';
        else if (pct <= -CHEAPER_PCT) cand.rec = 'PRICIER — ' + Math.round(-pct) + '% more than ' + pred.model + ' (' + cmp + '). Stay on ' + pred.model + ' unless you need the new capability.';
        else cand.rec = 'SAME PRICE as ' + pred.model + ' (' + cmp + '). Newer version at no extra cost: worth moving to.';
        cand.pct = pct;
      }
      candidates.push(cand);
    }
  }
});

// Parse-failure guard: nothing usable came back from Perplexity at all.
if (!anyParsed) {
  const title = '⚠️ llm-pricing check ' + today + ' — Perplexity lookups failed';
  const details = 'No Perplexity response could be parsed as JSON this run, for any provider — no comparison performed. Gaps: ' + gaps.join('; ').slice(0, 1500);
  return [{ json: { title, status: 'Pending', project: 'dlabs-toolkit', job: 'llm-pricing drift', details, bodyBlocks: [details] } }];
}

// Opportunities already in the table: newest model in a family is >=10% cheaper (blended) than an older sibling.
const opportunities = [];
for (const p of Object.keys(byProvider)) {
  const fams = {};
  for (const r of byProvider[p]) if (!r.alias && r.family && r.version.length && r.blend != null) (fams[r.family] = fams[r.family] || []).push(r);
  for (const f of Object.keys(fams)) {
    const arr = fams[f].sort((a, b) => cmpVer(b.version, a.version));
    if (arr.length < 2) continue;
    const newest = arr[0], older = arr[1];
    const pct = (older.blend - newest.blend) / older.blend * 100;
    if (pct >= CHEAPER_PCT) opportunities.push({ p, newest: newest.model, older: older.model, pct, nb: newest.blend, ob: older.blend });
  }
}
opportunities.sort((a, b) => b.pct - a.pct);

candidates.sort((a, b) => (b.pct == null ? -999 : b.pct) - (a.pct == null ? -999 : a.pct));
const candidatesTruncated = Math.max(0, candidates.length - MAX_CANDIDATES);
if (candidatesTruncated) candidates.length = MAX_CANDIDATES;

// Stale verification: table entries not re-verified in STALE_DAYS days (info only).
const stale = [];
for (const p of Object.keys(table)) {
  if (p === '$schema' || p === 'versionedAt' || typeof table[p] !== 'object') continue;
  for (const m of Object.keys(table[p])) {
    const v = table[p][m] && table[p][m].verifiedAt; if (!v) continue;
    const age = (Date.parse(today) - Date.parse(v)) / 86400000;
    if (age > STALE_DAYS) stale.push(p + '/' + m + ' (' + v + ')');
  }
}

const drifted = driftResults.filter(r => r.cls === 'DRIFT');
const unverifiable = driftResults.filter(r => r.cls === 'UNVERIFIABLE');
const verified = driftResults.filter(r => r.cls === 'MATCH');
const cheaper = candidates.filter(c => c.pct != null && c.pct >= CHEAPER_PCT);
const action = drifted.length + candidates.length + deprecations.length > 0;

const title = (action ? '⚠️' : '✅') + ' llm-pricing ' + today + ' — ' + (action
  ? [candidates.length ? candidates.length + ' new' + (cheaper.length ? ' (' + cheaper.length + ' cheaper)' : '') : '', drifted.length ? drifted.length + ' drift' : '', deprecations.length ? deprecations.length + ' deprecated' : ''].filter(Boolean).join(', ')
  : 'no changes');
const summary = 'versionedAt ' + table.versionedAt + '; ' + verified.length + ' verified, ' + unverifiable.length + ' unverifiable; ' +
  drifted.length + ' drifted; ' + candidates.length + ' new (' + cheaper.length + ' cheaper than predecessor); ' + deprecations.length + ' deprecated' +
  (gaps.length ? '; GAPS: ' + gaps.join(', ') : '');

let body = '';
if (gaps.length) body += '⚠️ COVERAGE GAPS (lookups that failed — absence of news for these providers means nothing): ' + gaps.join('; ') + '\n\n';
if (candidates.length) {
  body += 'NEW MODELS + RECOMMENDATIONS (' + candidates.length + ')\n';
  for (const c of candidates)
    body += '• ' + c.p + ' / ' + c.m + ' — in ' + money(c.in) + ' / out ' + money(c.out) + (c.status ? ' [' + c.status + ']' : '') + (c.released ? ' released ' + c.released : '') +
      (c.pred ? ' (succeeds ' + c.pred.model + ')' : '') + '\n    ' + c.rec + (c.notes ? '\n    note: ' + c.notes : '') + '\n';
  if (candidatesTruncated) body += '(+' + candidatesTruncated + ' more candidates not shown — re-run /llm-pricing-triage for the full list)\n';
  if (filteredNonText) body += '(' + filteredNonText + ' non-text models ignored: embeddings/image/audio/video)\n';
  body += '\n';
}
if (opportunities.length) {
  body += 'CHEAPER SUCCESSORS ALREADY IN THE TABLE (newest model in a family is >=' + CHEAPER_PCT + '% cheaper than the one before it, blended 3:1)\n';
  for (const o of opportunities.slice(0, 10)) body += '• ' + o.p + ' / ' + o.newest + ' is ' + Math.round(o.pct) + '% cheaper than ' + o.older + ' (' + money(o.nb) + ' vs ' + money(o.ob) + ')\n';
  body += '\n';
}
if (drifted.length) {
  body += 'PRICE DRIFT >= ' + THRESHOLD + '% (provider / model / table in->out / detected in->out / delta%)\n';
  for (const r of drifted) body += '• ' + r.p + ' / ' + r.m + ' / $' + r.tIn + '->$' + r.tOut + ' / $' + r.dIn + '->$' + r.dOut + ' / in ' + r.deltaIn + '% out ' + r.deltaOut + '%\n';
  body += '\n';
}
if (deprecations.length) {
  body += 'DEPRECATED / RETIRING (table models the provider now marks deprecated or gives a shutdown date)\n';
  for (const d of deprecations) body += '• ' + d.p + ' / ' + d.m + ' — ' + d.status + (d.shutdown ? ', shutdown ' + d.shutdown : '') + '\n';
  body += '\n';
}
if (unverifiable.length) {
  const byP = {};
  unverifiable.forEach(u => (byP[u.p] = byP[u.p] || []).push(u.m));
  body += 'UNVERIFIABLE (no reliable price found): ' + Object.keys(byP).map(p => p + ' ' + byP[p].length + ' (' + byP[p].slice(0, 6).join(', ') + (byP[p].length > 6 ? ', …' : '') + ')').join('; ') + '\n\n';
}
if (stale.length) body += 'STALE VERIFICATION (>' + STALE_DAYS + ' days since verifiedAt): ' + stale.length + ' — ' + stale.slice(0, 8).join(', ') + (stale.length > 8 ? ', …' : '') + '\n\n';
if (action) body += 'NEXT STEP: run /llm-pricing-triage in Claude Code — Tom verifies each flagged price and new model against the official pages, drafts the table edits, and posts the result to fleet-console > Updates. Never edit the table straight from this report.\n\n';
body += 'Notes: table updates never delete existing model keys — older models stay supported and are repriced (not removed). Blended price = (3×input + 1×output)/4 per 1M tokens; adjust for your real input:output mix. ' +
  'Perplexity pricing is probabilistic — verify against official provider pages before any table edit or migration.';

let details = summary + (candidates.length ? ' | ' + candidates.slice(0, 4).map(c => c.m).join(', ') + (candidates.length > 4 ? ', …' : '') : '');
if (details.length > NOTION_RT_MAX) details = details.slice(0, NOTION_RT_MAX - 3) + '...';
return [{ json: { title, status: action ? 'Pending' : 'Completed', project: 'dlabs-toolkit', job: 'llm-pricing drift', details, bodyBlocks: chunkText(body, 1900) } }];

// Fan the full report out to one n8n item per chunk so 'Append blocks' runs once per
// paragraph block. Reads from 'Compare (deterministic)' directly (not $input) because the
// upstream Notion create node returns the new page's own API response, not the input JSON.
const bodyBlocks = $('Compare (deterministic)').first().json.bodyBlocks || [];
if (bodyBlocks.length === 0) return [];
return bodyBlocks.map(chunk => ({ json: { chunk } }));
